// ============================================================
// App.js — ATUALIZADO com novas rotas
// Adicionado:
//   /auth/google/callback  → GoogleCallback
//   /settings/privacy      → PrivacySettings
// ============================================================
import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { AuthProvider, AuthContext } from './context/AuthContext';

// Páginas de autenticação
import Login from './pages/Login';
import Register from './pages/Register';
import GoogleCallback from './pages/GoogleCallback';   // ← NOVO

// Páginas principais
import Feed from './pages/Feed';
import Explore from './pages/Explore';
import Profile from './pages/Profile';
import Chat from './pages/Chat';
import Challenges from './pages/Challenges';
import Games from './pages/Games';
import Notifications from './pages/Notifications';
import Search from './pages/Search';
import Settings from './pages/Settings';
import PrivacySettings from './pages/PrivacySettings'; // ← NOVO

// Componentes
import Navbar from './components/Navbar';

// Rota protegida — redireciona para /login se não autenticado
const PrivateRoute = ({ children }) => {
  const { token, loading } = React.useContext(AuthContext);
  if (loading) return <div className="app-loading">Carregando...</div>;
  return token ? children : <Navigate to="/login" replace />;
};

// Rota pública — redireciona para /feed se já autenticado
const PublicRoute = ({ children }) => {
  const { token, loading } = React.useContext(AuthContext);
  if (loading) return <div className="app-loading">Carregando...</div>;
  return !token ? children : <Navigate to="/feed" replace />;
};

const AppRoutes = () => {
  const { token } = React.useContext(AuthContext);

  return (
    <>
      {token && <Navbar />}
      <Routes>
        {/* ── Rotas públicas ── */}
        <Route path="/" element={<Navigate to={token ? '/feed' : '/login'} replace />} />

        <Route path="/login" element={
          <PublicRoute><Login /></PublicRoute>
        } />

        <Route path="/register" element={
          <PublicRoute><Register /></PublicRoute>
        } />

        {/* Callback do Google OAuth — sempre acessível */}
        <Route path="/auth/google/callback" element={<GoogleCallback />} />

        {/* ── Rotas protegidas ── */}
        <Route path="/feed" element={
          <PrivateRoute><Feed /></PrivateRoute>
        } />

        <Route path="/explore" element={
          <PrivateRoute><Explore /></PrivateRoute>
        } />

        <Route path="/profile/:username?" element={
          <PrivateRoute><Profile /></PrivateRoute>
        } />

        <Route path="/chat" element={
          <PrivateRoute><Chat /></PrivateRoute>
        } />

        <Route path="/chat/:userId" element={
          <PrivateRoute><Chat /></PrivateRoute>
        } />

        <Route path="/challenges" element={
          <PrivateRoute><Challenges /></PrivateRoute>
        } />

        <Route path="/games" element={
          <PrivateRoute><Games /></PrivateRoute>
        } />

        <Route path="/notifications" element={
          <PrivateRoute><Notifications /></PrivateRoute>
        } />

        <Route path="/search" element={
          <PrivateRoute><Search /></PrivateRoute>
        } />

        <Route path="/settings" element={
          <PrivateRoute><Settings /></PrivateRoute>
        } />

        {/* ← NOVA ROTA: Configurações de Privacidade */}
        <Route path="/settings/privacy" element={
          <PrivateRoute><PrivacySettings /></PrivateRoute>
        } />

        {/* 404 */}
        <Route path="*" element={
          <div style={{
            display: 'flex', flexDirection: 'column', alignItems: 'center',
            justifyContent: 'center', minHeight: '100vh', color: '#fff',
            background: '#0a0a1a', gap: '16px'
          }}>
            <h1 style={{ fontSize: '4rem', margin: 0 }}>404</h1>
            <p style={{ color: 'rgba(255,255,255,0.5)' }}>Página não encontrada</p>
            <a href="/feed" style={{ color: '#a855f7', textDecoration: 'none' }}>← Voltar ao Feed</a>
          </div>
        } />
      </Routes>
    </>
  );
};

const App = () => (
  <AuthProvider>
    <Router>
      <AppRoutes />
    </Router>
  </AuthProvider>
);

export default App;
